/* From Uiverse.io by satyamchaudharydev - Tags: card */
.__UIV_SCOPE__ .card {
 --primary-clr: #1C204B;
 --dot-clr: #BBC0FF;
 --play: hsl(195, 74%, 62%);
 width: 200px;
 height: 170px;
 border-radius: 10px;
}

.__UIV_SCOPE__ .card {
 font-family: "Arial";
 color: #fff;
 display: grid;
 cursor: pointer;
 grid-template-rows: 50px 1fr;
}

.__UIV_SCOPE__ .card:hover .img-section {
 transform: translateY(1em);
}

.__UIV_SCOPE__ .card-desc {
 border-radius: 10px;
 padding: 15px;
 position: relative;
 top: -10px;
 display: grid;
 gap: 10px;
 background: var(--primary-clr);
}

.__UIV_SCOPE__ .card-time {
 font-size: 1.7em;
 font-weight: 500;
}

.__UIV_SCOPE__ .img-section {
 transition: 0.2s cubic-bezier(0.25, 0.46, 0.45, 0.94);
 border-top-left-radius: 10px;
 border-top-right-radius: 10px;
 background: hsl(195, 74%, 62%);
}

.__UIV_SCOPE__ .card-header {
 display: flex;
 align-items: center;
 width: 100%;
}

.__UIV_SCOPE__ .card-title {
 flex: 1;
 font-size: 0.9em;
 font-weight: 500;
}

.__UIV_SCOPE__ .card-menu {
 display: flex;
 gap: 4px;
 margin-inline: auto;
}

.__UIV_SCOPE__ .card svg {
 float: right;
 max-width: 100%;
 max-height: 100%;
}

.__UIV_SCOPE__ .card .dot {
 width: 5px;
 height: 5px;
 border-radius: 50%;
 background: var(--dot-clr);
}

.__UIV_SCOPE__ .card .recent {
 line-height: 0;
 font-size: 0.8em;
}
